%dw 2.0 output application/java
fun norm(value) = upper((value default "") as String)
fun isHoliday(day, holidays) = !isEmpty( holidays filter (h) -> (h as Date) == (day as Date) ) fun calculateAckDue(start, priority, ackMinutes, holidays) = if (upper(priority default "P3") == "P1") start + (("PT" ++ (ackMinutes as String {format: "0"}) ++ "M") as Period) else addBusinessMinutes(start, ackMinutes, holidays)
fun isBusinessDay(day, holidays) = (day as Date).dayOfWeek >= 1 and (day as Date).dayOfWeek <= 5 and not isHoliday(day, holidays)
fun nextBusinessStart(dt, holidays) = do { var day = dt as Date var start = day ++ |09:00:00| var finish = day ++ |17:00:00| --- if (not isBusinessDay(day, holidays) or dt >= finish) nextBusinessStart( (day + |P1D|) ++ |09:00:00|, holidays ) else if (dt < start) start else dt }
fun addBusinessMinutes(start, remaining, holidays) = if (remaining <= 0) start else do { var current = nextBusinessStart(start, holidays) var day = current as Date var finish = day ++ |17:00:00| var available = ((finish - current) as Number {unit: "minutes"}) --- if (remaining <= available) current + (("PT" ++ ((remaining as Number) as String {format: "0"}) ++ "M") as Period) else addBusinessMinutes( (day + |P1D|) ++ |09:00:00|, remaining - available, holidays ) }
var ticket = vars.ticketRequest var rules = vars.routingRules var holidays = (vars.holidays default []) map ((h) -> h.Holiday_Date__c as Date)
fun matches(ruleValue, ticketValue) = norm(ruleValue) == norm(ticketValue) or norm(ruleValue) == "ALL" or norm(ruleValue) == "ANY"
var matchingRules = (rules filter (r) -> lower((r.Is_Active__c default false) as String) == "true" and matches(r.Category_Code__c, ticket.category) and matches(r.Product_Code__c, ticket.product) and matches( r.Customer_Tier__c, ticket.customerTier default "STANDARD" ) and matches(r.Stated_Severity__c, ticket.severity) ) orderBy ((r) -> (r.Rule_Priority__c as Number) default 999)
var selectedRule = if (!isEmpty(matchingRules)) matchingRules[0] else (rules filter (r) -> r.Name == "RR-099")[0] default {}
var ackMinutes = (selectedRule.Ack_SLA_Minutes__c default 240) as Number
var resolutionHours = (selectedRule.Resolution_SLA_Hours__c default 72) as Number
var priority = upper(selectedRule.Assigned_Priority__c default "P3")
var acknowledgementDueAt = calculateAckDue( now(), priority, ackMinutes, holidays )
var resolutionDueAt = if (priority == "P1") now() + (("PT" ++ ((resolutionHours * 60) as String {format: "0"}) ++ "M") as Period) else addBusinessMinutes( now(), resolutionHours * 60, holidays )
--- [ { Subject__c: ticket.subject, Description__c: ticket.description, Category_Code__c: ticket.category, Product_Code__c: ticket.product, Customer_ID__c: ticket.customerId, Customer_Tier__c: ticket.customerTier default "STANDARD", Contact_Email__c: ticket.contactEmail, Request_ID__c: ticket.requestId, Stated_Severity__c: ticket.severity, Ticket_Status__c: "New", Priority__c: priority, Assigned_Team__c: selectedRule.Assigned_Team__c default "TRIAGE", Acknowledgement_Due_At__c: acknowledgementDueAt, Resolution_Due_At__c: resolutionDueAt
} ]
